[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]private static void AutoCreate(){if(FindAnyObjectByType<MainMenuController>()==null)new GameObject("DF_MainMenu").AddComponent<MainMenuController>();}public static void ShowHome(){if(instance==null){new GameObject("DF_MainMenu").AddComponent<MainMenuController>();return;}instance.gameObject.SetActive(true);instance.page=Page.Home;instance.visible=true;instance.launching=false;instance.openedAt=Time.unscaledTime;Time.timeScale=0f;}private void Awake(){if(instance!=null&&instance!=this){Destroy(gameObject);return;}instance=this;selectedHero=(int)PlayerHeroSelection.Selected;profileName=PlayerProfile.PlayerName;openedAt=Time.unscaledTime;Time.timeScale=0;dimTexture=MakeTexture(StylizedArtDirection.Ink);zeroTexture=MakeTexture(StylizedArtDirection.ZeroDark);lumenTexture=MakeTexture(StylizedArtDirection.LumenDark);whiteTexture=MakeTexture(Color.white);}private void OnEnable(){if(visible)Time.timeScale=0;}private void Update(){if(launching&&Time.unscaledTime-launchAt>.62f)EnterMatch();}
private Texture2D MakeTexture(Color c){Texture2D t=new Texture2D(1,1);t.SetPixel(0,0,c);t.Apply();return t;}private void OnDestroy(){if(instance==this)instance=null;DestroyTexture(dimTexture);DestroyTexture(zeroTexture);DestroyTexture(lumenTexture);DestroyTexture(whiteTexture);}private static void DestroyTexture(Texture2D t){if(t!=null)Destroy(t);}private void OnGUI(){if(!visible)return;EnsureStyles();DrawBackground();if(launching){DrawLaunch();return;}switch(page){case Page.Play:DrawPlay();break;case Page.Heroes:DrawHeroes();break;case Page.Shop:DrawShop();break;case Page.Profile:DrawProfile();break;case Page.Settings:DrawSettings();break;default:DrawHome();break;}}
