private void DrawShop(){float w=Mathf.Min(820,Screen.width*.92f),x=(Screen.width-w)*.5f,y=Screen.height*.075f;GUI.Label(new Rect(x,Screen.height*.015f,w,55),"DIMENSIONS FRONT • COSMETICS",title);Rect shopPanel=new Rect(x,y,w,Screen.height*.79f);DimensionUiMotif.DrawSplitPanel(shopPanel,whiteTexture,StylizedArtDirection.ZeroEnergy,StylizedArtDirection.LumenEnergy,Time.unscaledTime);GUI.Label(new Rect(x+25,y+15,w-50,28),$"{AvatarShopCatalog.CurrencyName}  ◆ {PlayerWallet.Balance}",subtitle);float leftW=w*.49f,rightX=x+w*.51f,rightW=w*.46f;GUI.Label(new Rect(x+20,y+52,leftW-30,30),"AVATAR COLLECTION",heroName);AvatarShopItem item=AvatarShopCatalog.Items[Mathf.Clamp(shopAvatarIndex,0,AvatarShopCatalog.Items.Length-1)];Rect avatarCard=new Rect(x+28,y+92,leftW-45,235);DimensionUiMotif.DrawSplitPanel(avatarCard,whiteTexture,StylizedArtDirection.ZeroEnergy,StylizedArtDirection.LumenEnergy,Time.unscaledTime);GUI.Label(new Rect(avatarCard.x+10,avatarCard.y+18,avatarCard.width-20,34),item.Name,subtitle);GUI.Label(new Rect(avatarCard.x+10,avatarCard.y+58,avatarCard.width-20,24),item.Theme,small);GUI.Label(new Rect(avatarCard.x+10,avatarCard.y+96,avatarCard.width-20,40),$"◆ {item.Price} SHARDS",heroName);bool owned=AvatarInventory.IsOwned(item.AvatarId);GUI.enabled=!owned&&PlayerWallet.CanAfford(item.Price);if(GUI.Button(new Rect(avatarCard.x+avatarCard.width*.15f,avatarCard.y+154,avatarCard.width*.70f,44),owned?"OWNED":"UNLOCK",primary)){AvatarPurchaseResult result=AvatarShopService.TryPurchase(item);shopMessage=result==AvatarPurchaseResult.Purchased?"AVATAR UNLOCKED":result==AvatarPurchaseResult.InsufficientShards?"NOT ENOUGH SHARDS":result.ToString().ToUpperInvariant();}GUI.enabled=true;if(GUI.Button(new Rect(avatarCard.x+15,avatarCard.y+205,52,28),"‹",button))shopAvatarIndex=(shopAvatarIndex-1+AvatarShopCatalog.Items.Length)%AvatarShopCatalog.Items.Length;if(GUI.Button(new Rect(avatarCard.x+avatarCard.width-67,avatarCard.y+205,52,28),"›",button))shopAvatarIndex=(shopAvatarIn